## What is the current behavior?

I tried to use all the lifecycle hooks methods in a module (and its service) that was lazy loaded but none of them was called. But I didn't find any mention on the docs site regarding that behavior.

<details><summary>demo</summary>

![image](https://user-images.githubusercontent.com/13461315/162590264-f5938230-57f8-4c37-935e-338088632138.png)

```ts
// app.service.ts
@Injectable()
export class AppService {
  constructor(private readonly lazyModuleLoader: LazyModuleLoader) {}
  async getHello(): Promise<string> {
    const { LazyModule } = await import('./lazy.module');
    const moduleRef = await this.lazyModuleLoader.load(() => LazyModule);
    const lazyService = moduleRef.get(LazyService);
    return lazyService.getHello();
  }
}
```

```ts
// app.module.ts
@Module({
  imports: [],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {
  onModuleInit() {
    console.log('[nestjs] AppModule initialized')
  }
}
```

```ts
// lazy.service.ts
@Injectable()
export class LazyService {
  onModuleInit() {
    console.log('A')
  }
  onApplicatoinBootstrap() {
    console.log('B')
  }
  onModuleDestroy() {
    console.log('C')
  }
  beforeApplicationShutdown() {
    console.log('D')
  }
  onApplicationShutdown() {
    console.log('E')
  }

  getHello(): string {
    return 'Hello World From lazy service!';
  }
}
```

```ts
// lazy.module.ts
console.log('[nodejs] lazy.module.ts loaded')
@Module({
  providers: [LazyService],
})
export class LazyModule {
  onModuleInit() {
    console.log('A')
  }
  onApplicatoinBootstrap() {
    console.log('B')
  }
  onModuleDestroy() {
    console.log('C')
  }
  beforeApplicationShutdown() {
    console.log('D')
  }
  onApplicationShutdown() {
    console.log('E')
  }
}
```

</details>

## What is the new behavior?

I'm not sure what's the best way to document that, but we should mention that those lifecycle hooks methods are not called on lazy loaded modules. 


## Does this PR introduce a breaking change?
- [ ] Yes
- [x] No

`getRequestBody` returns `nil` if the original API Gateway request had an empty body. This can result in a surprise later on if a handler is blindly reading the request's body without checking it isn't nil:

```go
func myHandler(w http.ResponseWriter, r *http.Request) {
	bs, err := io.ReadAll(r.Body) // panic: runtime error: invalid memory address or nil pointer dereference
	// ...
}
```

I believe `http.NoBody` is the correct value used by the Go standard library to set an empty request body.

```go
// server.go:3512
func (h initALPNRequest) ServeHTTP(rw ResponseWriter, req *Request) {
	if req.TLS == nil {
		req.TLS = &tls.ConnectionState{}
		*req.TLS = h.c.ConnectionState()
	}
	if req.Body == nil {
		req.Body = NoBody
	}
// ...
}
```
